#!/bin/bash
# reading-only PTX/cubin (head dim 128; bf16/bf16 and f16/fp8 decode; all six cache-kernel pairs) of the v0.9.4
# flashinfer_decode.cu: the full TU's cicc needs > 4 GB (segfaults under the 4G cap). Same flags as nvcc_094.sh.
cd $HOME/titan-engine/oxide-pattn/mistralrs-paged-attn-b/ref094/reduced && /usr/local/cuda/bin/nvcc -std=c++17 -O3 -U__CUDA_NO_HALF_OPERATORS__ -U__CUDA_NO_HALF_CONVERSIONS__ -U__CUDA_NO_HALF2_OPERATORS__ -U__CUDA_NO_BFLOAT16_CONVERSIONS__ --expt-relaxed-constexpr --expt-extended-lambda --use_fast_math --compiler-options -fPIC -DENABLE_FP8 -gencode=arch=compute_120a,code=sm_120a --default-stream per-thread -allow-unsupported-compiler -ccbin /usr/bin/g++-15 -I$HOME/titan-engine/top-pattn/mr-pattn/mistralrs-paged-attn/src/cuda --ptx -o fi_reduced.ptx fi_reduced.cu && /usr/local/cuda/bin/nvcc -std=c++17 -O3 -U__CUDA_NO_HALF_OPERATORS__ -U__CUDA_NO_HALF_CONVERSIONS__ -U__CUDA_NO_HALF2_OPERATORS__ -U__CUDA_NO_BFLOAT16_CONVERSIONS__ --expt-relaxed-constexpr --expt-extended-lambda --use_fast_math --compiler-options -fPIC -DENABLE_FP8 -gencode=arch=compute_120a,code=sm_120a --default-stream per-thread -allow-unsupported-compiler -ccbin /usr/bin/g++-15 -I$HOME/titan-engine/top-pattn/mr-pattn/mistralrs-paged-attn/src/cuda --cubin -o fi_reduced.cubin fi_reduced.cu
